//! Файл: settings/catalog/dex_event.rs
//! Что делает: настройки перечитывания пула по событию (задача t144, живой случай SHOPINX 16.11.2026): решение 313 —
//! замер перечитывания и счётчик потерянных событий пулов (раздел «Система», вся система). Отдельный файл: каталоги
//! base.rs и dex.rs — общие для многих задач. Решение 314 — класс очереди узла для перечитываний по событию (раздел
//! «DEX», область «площадка», только площадка DEX — .dex_venue()); решение 315 — пул V3 одним обращением к узлу при
//! перечитывании по событию (там же); решение 321 — события пулов не теряются при полном канале ядра (там же);
//! решение 325 — перечитывание по событию с ответами, прочитанными заранее, и «только комиссия» у Algebra Integral
//! (раздел «DEX», область «DEX» — по одному DEX). Все
//! необязательные, значений нет. Решение 332 — перечитывание пула из бинов (Infinity Bin, LB V2.1), когда цена ушла за
//! прочитанную полосу бинов (раздел «Контракты DEX», область «DEX» — включается по одной DEX); ревью 332 — частота
//! записей журнала log.bin_reread_interval_s (раздел «Система»). Решение 339 (журнал обрывов, t153) —
//! log.pool_break_interval_s (раздел «Система»).
//! Кто вызывает: settings/catalog/mod.rs.
//! От чего зависит: settings/catalog/mod.rs (короткая запись d и наборы областей).
//! Настройки: это и есть их список (зеркало docs/SETTINGS.md, разделы «Система», «DEX» и «Контракты DEX»).

use super::{DX, G, V, d};
use crate::settings::schema::{Kind as K, Limit as L, SettingDef};

/// Настройки решений 313–315, 321, 325, 332, 339 (журнал обрывов). Порядок — по решениям; в docs/SETTINGS.md каждая
/// стоит в таблице своего раздела («Система», «DEX», «Контракты DEX») — ревью 332 (Н5).
#[rustfmt::skip]
pub static DEX_EVENT: &[SettingDef] = &[
    d("Система", "log.pool_refresh_timing", K::Bool, L::None, "да/нет", G, "Решение 313 (включаемое, для разбора): замер перечитывания пула ПО СОБЫТИЮ (полоса цены вышла за прочитанные слова карты тиков — off_map; событие требует перечитать пул — refresh) — запись журнала dex.pool_refresh на каждое такое перечитывание: DEX, пул, причина, блок события и блок чтения, общее время, каждое обращение к узлу BSC отдельно (ожидание в очереди темпа узла / сам запрос, вызовов в нём), класс очереди узла, слов карты тиков, сколько сообщений ждало в канале сессии пачки к концу, итог. Нет или не задана — замера нет (одно чтение настройки на перечитывание). Необязательна").optional(),
    d("Система", "log.pool_events_lost_interval_s", K::Integer, L::Positive, "секунды", G, "Решение 313: событие пула (MarketEvent::Pool) не ушло ядру, потому что канал событий ядра полон (отправка без ожидания, чтобы медленное ядро не задерживало чтение событий; раньше терялось молча). Каждая потеря считается; запись журнала dex.pool_events_lost (Warn) с числом потерь с прошлой записи — не чаще раза в столько секунд (первая — сразу). Не задана — записей нет, отправка как раньше. Решение 324: тот же интервал у записи venue.book_events_lost о стаканах бирж (отложено, заменено, доставлено, потеряно, ждут — по площадке). Необязательна. Решение 424: тот же интервал — у сводки venue.book_fast о быстром стакане Poloniex (переходы на быстрый / на снимки, разрывы, переподписки — по соединению)").optional(),
    d("Система", "log.pool_break_interval_s", K::Integer, L::Positive, "секунды", G, "Решение 339 (журнал обрывов, t153): каждый обрыв сессии подписки пачки пулов DEX пишется в журнал venue.ws (Warn): имя пачки, число пулов, причина целиком. Одинаковая запись (та же пачка, та же причина без чисел и hex) — не чаще раза в столько секунд; пропущенные считаются и называются в следующей записи этой пачки с этой причиной. Не задана — запись на каждый обрыв. Прежние записи «Связь с узлом BSC (WebSocket) потеряна / восстановлена» — как раньше. Необязательна").optional(),
    d("DEX", "dex.event_refresh_urgency", K::Choice, L::None, "класс", V, "Решение 314: класс очереди узла BSC (срочность, gateway/urgency.rs: trade → check → quote → background, строгий порядок с долей фона bsc.node_background_share_pct) для перечитываний пула, вызванных событием пула в сессии слушателя: полоса цены вышла за карту тиков (off_map), событие требует перечитать пул (реорг, расхождение), бины на блоке события, одна перечитка пар многомонетного пула, пары общего контракта WooFi по логу. Класс действует только на время этого чтения — остальная работа сессии остаётся фоновой. trade — наравне с путём сделки (расчёт кандидата, предпроверка, исполнение — по приходу внутри класса); check — после пути сделки, наравне с проверками монет; quote — наравне с котировками живого экрана. Не задана — как раньше: класс сессии не задан (background)").choices(&["trade", "check", "quote", "background"]).dex_venue().optional(),
    d("DEX", "dex.event_refresh_one_call", K::Bool, L::None, "да/нет", V, "Решение 315: перечитывание пула V3 (ABI PancakeSwap V3 / Uniswap V3) по событию (полоса цены вышла за карту тиков — off_map; событие требует перечитать пул) ОДНИМ обращением к узлу: slot0, liquidity, [swapFee фабрики — решение 274], [fee() пула — решение 281] и слова карты TickLens одним eth_call к Multicall3 (dex.multicall3) на блоке чтения; слова — вокруг тика записи после события, настоящий диапазон проверяется по slot0 того же ответа (внутри — лишние слова отбрасываются, иначе второе обращение за словами того же блока). Итог тот же, что у последовательного чтения на этом блоке (не меньше трёх обращений). Работает только при заданном dex.multicall3. Нет или не задана — как раньше").dex_venue().optional(),
    d("DEX", "dex.event_refresh_batch", K::Bool, L::None, "да/нет", DX, "Решение 325 (область «DEX» — включается по одному DEX и так же откатывается): перечитывание пула этого DEX по событию (полоса цены вышла за карту тиков — off_map; событие требует перечитать пул — реорг, расхождение, Mint/Burn у Algebra) с ответами, прочитанными ЗАРАНЕЕ одним обращением к узлу (eth_call к Multicall3.aggregate3; больше dex.load_batch вызовов — частями): вызовы прошлого перечитывания этого пула + то, что вид знает заранее (голова, слова карты вокруг тика события; у Algebra Integral — дерево тиков и цепочка списка), затем по ответам — зависящее от них (слова настоящего диапазона, тики по битам) следующим обращением. Прежний код чтения идёт с этими ответами: что прочитано — без узла, чего нет — к узлу как раньше; итог тот же, что у последовательного чтения на том же блоке (тот же код и разбор). Обычно 1–2 обращения вместо цепочки (Integral — 4–5 + до 2 × dex.integral_tick_steps, CL/Slipstream/Algebra V1.9 — 4, Elastic — 5, DODO — 4). Ревью 325: обращение заранее делится на части по dex.load_batch, но частей не больше, чем вызовов, которые код чтения делал бы по одному, — у Elastic и Integral обращений не больше, чем без настройки, при любом dex.load_batch. Бины событий Infinity Bin и LB от этой настройки не зависят: они всегда читаются одной пачкой вместе с активным бином (решение 357). Решение 315 (dex.event_refresh_one_call) для V3 PancakeSwap/Uniswap ABI — раньше этой. Перечитыванию пула нужны dex.multicall3 и dex.load_batch. Значение — в памяти, смена действует на лету. Нет или не задана — как раньше").optional(),
    d("DEX", "dex.event_refresh_fee_only", K::Bool, L::None, "да/нет", DX, "Решение 325 (область «DEX»): у пула Algebra Integral этого DEX событие, меняющее только комиссию (Fee — новая lastFee; SwapFee или Swap 1.2.0/1.2.1 с overrideFee = 0 и pluginFee ≠ 0 — цена, ликвидность и тик уже взяты из события), перечитывает ТОЛЬКО комиссию: globalState и fee() одним обращением на блоке события, правило то же, что у полного чтения (DYNAMIC_FEE — fee() пула, иначе lastFee); дальше — как обычное событие (полоса цены вышла за карту — перечитывание карты). Ревью 325: только у достоверного пула с состоянием Algebra и не ждущего повтора — иначе полное перечитывание, как раньше; замер (log.pool_refresh_timing) — запись dex.pool_refresh с причиной «fee». Раньше — полное перечитывание пула с обходом списка тиков. Значение — в памяти, смена действует на лету. Нет или не задана — как раньше (полное перечитывание, та же запись журнала)").optional(),
    d("DEX", "dex.pool_events_keep", K::Bool, L::None, "да/нет", V, "Решение 321: событие пула (MarketEvent::Pool), не вошедшее в канал событий ядра (канал полон — ёмкость --live-buffer), НЕ теряется: последнее событие каждого пула ждёт в наборе (не больше числа пулов, без дублей) и уходит ядру, как только в канале появится место — сначала ждущие, по очереди; новые события, пока кто-то ждёт, встают за ними. Пул, ставший недостоверным или снятый с подписки, пока ждал, не отправляется. Запись журнала dex.pool_events_lost (интервал log.pool_events_lost_interval_s) — «отложено, заменено, доставлено, снято, ждут». Выключение действует, когда ждущие пулы площадки доставлены. Решение 324: набор и доставщик — общие на канал ядра со стаканами бирж; включать вместе с venue.book_events_keep — иначе ждущие пулы забирают каждое освободившееся место раньше кадров стаканов (потери переезжают с пулов на стаканы). Нет или не задана — как раньше: событие при полном канале потеряно (счёт потерь решения 313)").dex_venue().optional(),
    d("Контракты DEX", "dex.bin_reread_left_pct", K::Decimal, L::PercentOpen, "%", DX, "Необязательная. Решение 332 (задача t154): пулы из бинов — PancakeSwap Infinity Bin (dex.kind pancakeswap_infinity_bin) и Liquidity Book V2.1 (lb_v21). Бот держит в памяти не все бины пула, а полосу вокруг активного: каждая сторона читается до стоимости dex.bin_depth_usd. После события бинов (обмен, ввод или вывод ликвидности) считается, сколько прочитано в каждую сторону от НОВОГО активного бина; если хотя бы в одну сторону меньше этого процента от dex.bin_depth_usd (или активный бин ушёл за полосу) — пул сразу перечитывается целиком на блоке события (тот же путь, что перечитывание V3 по выходу за карту тиков; класс очереди узла — dex.event_refresh_urgency). Сторона, прочитанная до конца пула, не проверяется. Пример: dex.bin_depth_usd = 1000, здесь 50 — после чтения в каждую сторону ≥ 1000 USDT; обмены съели вверх 600 USDT прочитанных бинов, осталось 400 < 500 — пул перечитан; осталось 600 — нет. Без неё после сильного движения цены пул выглядит мелким (расчёт обмена и глубина — только до края полосы) до переподключения или перезапуска. Цена: одно перечитывание пула (getSlot0 / состояние и обход бинов до dex.bin_depth_usd в обе стороны), не чаще раза на блок на пул; сразу после чтения повтора нет, пока не съедено больше (100 − процент)% прочитанного. Советуем процент так, чтобы dex.bin_depth_usd × процент / 100 было не меньше dex.min_pool_liquidity_usd. У пары LB без USDT не действует (там читаются все бины). Больше 0 и меньше 100. Задаётся по id DEX. Не задана — как раньше: бины вне полосы не читаются до переподключения").optional(),
    d("Система", "log.bin_reread_interval_s", K::Integer, L::Positive, "секунды", G, "Ревью решения 332 (пулы из бинов — Infinity Bin, LB V2.1; dex.bin_reread_left_pct): записи журнала dex.pool о проверке «цена ушла за прочитанную полосу бинов» — Info «пул перечитывается вокруг нового активного бина» и Warn «проверка не считается» (decimals встречного токена ещё не известны или стоимость бина не считается — тогда пул НЕ перечитывается и может остаться мелким: расчёт обмена и глубина только до края прочитанной полосы) — каждая не чаще раза в столько секунд на пул (первая — сразу). На перечитывание не влияет. Не задана — этих записей нет. Необязательна").optional(),
];
